answer = []
for article in sources:
    number = article['number']
    proposed = Path('proposed_' + number.replace(' ', '_') + '.xml').read_text().strip()
    item = {key: article[key] for key in ('code_id', 'source_id', 'source_sha256', 'number')}
    item.update(proposed_xml=proposed, **metadata[number], status='rewrite_draft')
    answer.append(item)

Path('answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
print(f'answer.json : {len(answer)} articles')
print('SHA-256 du fichier source.json :', hashlib.sha256(Path('source.json').read_bytes()).hexdigest())
